// =====================================================
// HTTP STATUS CODE CHEAT SHEET Generated By ChatGPT
// =====================================================

// 2xx Success
// 200 OK            → Request succeeded (GET, PUT, DELETE)
// 201 Created       → Resource successfully created (POST)
// 204 No Content    → Success with no response body (common for DELETE)

// 4xx Client Errors
// 400 Bad Request   → Missing or invalid input (validation errors)
// 401 Unauthorized  → Not authenticated (login required)
// 403 Forbidden     → Authenticated but not allowed
// 404 Not Found     → Resource does not exist
// 409 Conflict      → Duplicate or conflicting data (e.g., unique constraint)

// 5xx Server Errors
// 500 Internal Server Error → Generic server/database failure
// 503 Service Unavailable   → Server temporarily down or overloaded

// =====================================================
// QUICK USAGE GUIDE (for THIS project)
//
// POST   → 201 (or 400 / 500)
// GET    → 200 (or 404 / 500)
// PUT    → 200 (or 400 / 404 / 500)
// DELETE → 200 or 204 (or 404 / 500)
// =====================================================


// Basic setup
const express = require('express')
const cors = require('cors')
const sqlite3 = require('sqlite3').verbose()
const { v4: uuidv4 } = require('uuid') 
const path = require('path')
require('dotenv').config()

const app = express()
const PORT = 8000

// Shared API response and validation help for predictable response (AI slightly assisted in formatting, I chose limits)
const objFieldMaxLengths = {
    strProfileName: 128,
    strEmail: 256,
    strPhone: 32,
    strLocation: 128,
    strURL: 256,
    strJobTitle: 128,
    strCompany: 128,
    strDetail: 512,
    strCategory: 100,
    strSkill: 100,
    strCertName: 128,
    strIssuer: 128,
    strAwardName: 128,
    strAwardDescription: 650
}

// Centralized responses to make sure all endpoints return a much more consistent shape (success/message/data or error),
// which theoretically makes frontend handling predictable and allowing changes to response format in one place without total chaos
const sendSuccess = (res, intStatusCode, strMessage, objData = {}) => {
    return res.status(intStatusCode).json({
        success: true,
        message: strMessage,
        data: objData
    })
}

const sendError = (res, intStatusCode, strMessage, objError = {}) => {
    return res.status(intStatusCode).json({
        success: false,
        message: strMessage,
        error: { code: objError.code || "ERROR", details: objError.details || {} }
    })
}

// this safely trims any input without throwing on null or non-string values from req.body, superior to the previous way I was doing it
const safeTrim = (objValue) => {
    if (objValue === null || objValue === undefined) {
        return ""
    }
    return String(objValue).trim()
}

// checks if a string's length is within a specified maximum limit.
const isValidLength = (strValue, intMaxLength) => strValue.length <= intMaxLength


// Middleware stuff
app.use(cors())
app.use(express.json())

// Ai used for this
app.use(express.static(path.join(__dirname, '..', 'frontend')))

//Database connection
const db = new sqlite3.Database('resume.db', (err) => {
    if (err){
        console.error("Db connection error:", err.message)
    } else {
        console.log("Connected to SQLite database")
    }
})

// This a route to test connection
app.get('/ping', (req,res) => {
    return sendSuccess(res, 200, 'Server is alive', {})
})

// Serve frontend SPA from express
app.get('/', (req,res) => {
    res.sendFile(path.join(__dirname, '..', 'frontend', 'index.html'))
})


